//   const minimapElement = document.getElementById('minimap');
//   if (minimapElement) {
//       minimapElement.scrollTop = minimapElement.scrollHeight;
//   }
// }
function updateMinimapScroll() {
  getSourceScrollContainer();

  if (!sourceScrollContainer || !minimap) return;

  // 找到当前在视口中的对话回合
  const turns = sourceScrollContainer.querySelectorAll('[data-testid^="conversation-turn-"]');
  let visibleTurn = null;

  for (const turn of turns) {
      const rect = turn.getBoundingClientRect();
      if (rect.top < window.innerHeight / 2 && rect.bottom > window.innerHeight / 2) {
          visibleTurn = turn;
          break;
      }
  }

  if (visibleTurn) {
      const turnId = visibleTurn.getAttribute('data-testid');
      const minimapTurn = minimap.querySelector(`[data-testid-extension="${turnId}"]`);

      if (minimapTurn) {
          // 滚动 minimap 使对应元素居中
          const minimapCenter = minimap.offsetHeight / 2;
          minimap.scrollTop = minimapTurn.offsetTop - minimapCenter + minimapTurn.offsetHeight / 2;
      }
  }
}

{
  "manifest_version": 3,
  "name": "Scroll Minimap for Chatgpt",
  "version": "1.0",
  "description": "A minimap for scrolling through chatgpt messages, similar to the one in VS Code.",
  "action": {
    "default_popup": "popup.html"
  },
  "content_scripts": [
    {
      "js": [
        "content.js"
      ],
      "css": [
        "styles.css"
      ],
      "matches": [
        "https://chatgpt.com/*"
      ],
      "runAt": "document_idle"
    }
  ],
  "icons": {
    "128": "logo.png"
  },
  "permissions": [
    "activeTab"
  ]
}

#extension-container {
  position: fixed;
  top: 50px;
  right: 20px;
  display: flex;
  width:auto;
}

#option-container {
  transform: rotate(270deg);
  transform-origin: bottom right;
  width: fit-content;
  height: fit-content;
}

#option-container > button {
  background-color: rgb(200, 200, 200);
  border-top-right-radius: 1rem;
  border-top-left-radius: 1rem;
  padding: 0 0.5rem;
  padding-top: 0.1rem;
}

#minimap {
  position: relative;
  top: 0;
  background-color: #ffffffcc;
  box-shadow: 0 0 5px #00000033;
  border-radius: 15px;
  z-index: 1000;
  width: 25vw;
  height: 80vh;
  overflow-y: scroll;
  overflow-x: hidden;
}
.minimap-user-turn {
  padding: 5px;
  margin-bottom: 5px;
  border-radius: 4px;
  background-color: #e6f7ff; 
  font-weight: bold;
}

.minimap-ai-turn {
  max-height: 100px; 
  overflow: hidden;
  position: relative;
  margin-bottom: 5px;
  padding: 5px;
  border-radius: 4px;
  color: gray;
}

.minimap-ai-turn::after {
  content: '...';
  position: absolute;
  bottom: 0;
  right: 0;
  padding: 0 5px;
  background-color: inherit;
}

#target-elements [class^="minimap-user-turn"]:hover {
  background-color: #7FA1C3;
  cursor: pointer;
}

#target-elements {
  position: relative;
  z-index: 1001; 
  width: 100%;
  height: 100%;
  pointer-events: auto;
}
